import type { Request, Response } from 'express';
import type { ParamsDictionary } from 'express-serve-static-core';
import { z } from 'zod';
import { SearchUsersBody } from '@api/schemas.zod';
import { userService } from '../service';
import { successResponse } from '@infrastructure/http/response';
import { readInput } from '@infrastructure/http/request';
import { pageSchema, pageSizeSchema } from '@infrastructure/http/schemas';
import type { SearchUsersRequest } from '@types';
import { catchAs, parseBody } from '@infrastructure/http/controller';

/**
 * Query parameters generated by the search form
 */
export type GetUsersQuery = Partial<Record<keyof SearchUsersRequest, string>>;

/**
 * Built on the orval-generated SearchUsersBody (kept in sync with
 * openapi.yaml); page/pageSize and the three booleans are coerced from strings since GET
 * requests carry them as query-string text, not JSON numbers/booleans.
 *
 * `page`/`pageSize` come from `@infrastructure/http/schemas` so all four search endpoints agree on what a
 * legal one is; absent stays absent, because `normalizePagination` owns the defaults.
 */
/** A boolean as a query string spells it. Named once: three filters here need the same coercion. */
const queryBoolean = z.preprocess(
    (value) => (typeof value === 'string' ? value === 'true' : value),
    z.boolean().optional()
);

const searchUsersQuerySchema = SearchUsersBody.extend({
    page: pageSchema,
    pageSize: pageSizeSchema,
    active: queryBoolean,
    admin: queryBoolean,
    verified: queryBoolean
});

/**
 * Query parameters that change this endpoint's answer, and therefore its cache key.
 *
 * Derived from the schema rather than hand-listed, because the two must not drift: a parameter
 * the controller reads but the key omits would let two different requests share one cached
 * response. Anything outside this list is stripped by the validator and changes nothing.
 */
export const searchUsersKeyParameters = Object.keys(searchUsersQuerySchema.shape);

/**
 * GET /users
 * List/search users via query parameters (admin only).
 */
export const getUsers = (
    request: Request<ParamsDictionary, unknown, SearchUsersRequest, GetUsersQuery>,
    response: Response
) => {
    // One declaration instead of a per-field assembly — see docs/theory/request-input.md.
    const input = readInput(request, { surface: 'search', ids: ['id'] });

    const parsed = parseBody(searchUsersQuerySchema, input, response);
    if (!parsed) return;

    return userService
        .search(parsed)
        .then((result) => {
            successResponse(response, result);
        })
        .catch(catchAs(response, 'getUsers'));
};
